import { Injectable, isDevMode } from '@angular/core';
import { catchError, Observable, of, tap } from 'rxjs';
import { AppSettings } from '../../data/types/app-settings';
import { HttpCrudService } from './http-crud.service';

@Injectable({
  providedIn: 'root'
})
export class AppSettingsService {

  private isDevMode = isDevMode;

  private configInternal: AppSettings | null = null;

  public get config(): AppSettings | null {
    return this.configInternal;
  }

  constructor(private httpCrudService: HttpCrudService) {

  }

  public loadConfig(): Observable<AppSettings | null> {
    if (this.configInternal) {
      return of(this.configInternal);
    }
    return this.loadSettings().pipe(tap(x => this.configInternal = x));
  }

  private loadSettings(): Observable<AppSettings | null> {
    const fileName = this.isDevMode() ? 'config.development.json' : 'config.production.json';
    return this.httpCrudService.getJsonFile(`/configs/`.appendPath(fileName))
      .pipe(catchError(() => of(null)));
  }

}
