import { AppSettings } from '../../data/types/app-settings';
import { StringHelper } from './string.helper';

export class ConfigErrorHelper {

  public static getErrorMessage(appSettings: AppSettings | null): string | undefined {
    if (!appSettings) {
      return 'app-settings is missing';
    }

    if (StringHelper.isNullOrEmpty(appSettings.endPointUrl)) {
      return 'app-settings: endPointUrl is missing';
    }

    if (!appSettings.keycloak) {
      return 'app-settings: keycloak is missing';
    }

    if (StringHelper.isNullOrEmpty(appSettings.keycloak.authServerUrl)) {
      return 'app-settings: keycloak.authServerUrl is missing';
    }

    if (StringHelper.isNullOrEmpty(appSettings.keycloak.realm)) {
      return 'app-settings: keycloak.realm is missing';
    }

    if (StringHelper.isNullOrEmpty(appSettings.keycloak.resource)) {
      return 'app-settings: keycloak.resource is missing';
    }

    return undefined;
  }

}
